package com.narada.android

import com.narada.connection.*
import java.util.UUID
import java.util.concurrent.TimeUnit
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.first
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

/** Fake crypto/peer lifecycle campaign, never counted as native security evidence. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [35], application = android.app.Application::class)
class AttachmentsCoordinatorTest {
    private lateinit var f: ContentCoordinatorFixture
    @Before fun setup() = runBlocking<Unit> { f = ContentCoordinatorFixture(); f.setup() }
    @After fun close() = runBlocking<Unit> { if (::f.isInitialized) f.close() }
    @Test fun consentAndDurableIntentPrecedeCapabilityProbeAndPicker() = runBlocking<Unit> { f.attachmentView(); f.attachments.prepareImport("", false); f.attachmentState { it.error == "LOCAL_CONFIRMATION_REQUIRED" }; assertEquals(0, f.probes.get()); assertTrue(f.repo.doc.attachments.isEmpty()); val p = f.picker(); assertEquals(AttachmentState.PICKER_PENDING, f.repo.doc.attachment(p.id).state); assertEquals(1, f.probes.get()); assertEquals(0, f.imports.get()) }
    @Test fun completedImportQueuesManifestButNeverStartsChatOrByteUpload() = runBlocking<Unit> { val r = f.saved(); assertNotNull(r.receipt); assertFalse(r.remoteStored); assertEquals(ChatStatus.QUEUED, f.repo.doc.chat!!.message(r.messageId).status); assertEquals(1, f.imports.get()); f.attachments.run(r.id, true); f.attachmentState { it.error == "ATTACHMENT_MESSAGE_PENDING" }; assertTrue(f.repo.doc.attachment(r.id).available) }
    @Test fun matchingPickerResultIsSingleUseAndWrongTicketHasNoProviderAuthority() = runBlocking<Unit> { f.attachmentView(); val p = f.picker(); assertFalse(f.attachments.claimPicker(p.ticketId)); f.attachments.pickerResult(UUID.randomUUID().toString(), "content://fixture.documents/document/source", 1); delay(60); assertEquals(0, f.imports.get()); assertEquals(p, f.attachments.state.value.picker); f.attachments.pickerResult(p.ticketId, "content://fixture.documents/document/source", 1); f.attachmentState { it.rows.singleOrNull()?.available == true && !it.busy }; f.attachments.pickerResult(p.ticketId, "content://fixture.documents/document/source", 1); delay(60); assertEquals(1, f.imports.get()) }
    @Test fun factoryRefusalTerminalizesConsumedImportIntentWithoutOpeningProvider() = runBlocking<Unit> { f.attachmentView(); f.failImportFactory = true; val p = f.picker(); f.attachments.pickerResult(p.ticketId, "content://fixture.documents/document/source", 0); f.attachmentState { it.error == "PROVIDER_PERMISSION_LOST" }; assertEquals(AttachmentState.CANCELLED, f.repo.doc.attachment(p.id).state); assertNull(f.attachments.state.value.picker); assertTrue(f.repo.doc.chat!!.messages.isEmpty()); assertEquals(1L, f.opened.count) }
    @Test fun factoryRefusalTerminalizesExportAsNotCreatedAndRetainsVerifiedCopy() = runBlocking<Unit> { val r = f.saved(); f.failExportFactory = true; f.attachments.prepareExport(r.id, "copy.bin", true); val p = f.attachmentState { it.picker != null }.picker!!; assertTrue(f.attachments.claimPicker(p.ticketId)); f.attachments.pickerResult(p.ticketId, "content://fixture.documents/tree/root", 1); f.attachmentState { it.rows.single().exports.singleOrNull()?.state == ExportState.NOT_CREATED }; assertTrue(f.repo.doc.attachment(r.id).available); assertEquals(0, f.creates.get()) }
    @Test fun reloadingAbandonsOldPickerAndCannotRebindItsLateSelection() = runBlocking<Unit> { f.attachmentView(); val old = f.picker(); f.attachments.reload(); f.attachmentState { it.picker == null && it.rows.singleOrNull()?.state == AttachmentState.CANCELLED }; val fresh = f.picker(); f.attachments.pickerResult(old.ticketId, "content://fixture.documents/document/source", 1); delay(60); assertEquals(fresh, f.attachments.state.value.picker); assertEquals(0, f.imports.get()); f.attachments.pickerResult(fresh.ticketId, null, 0); f.attachmentState { it.picker == null && it.rows.find { row -> row.id == fresh.id }?.state == AttachmentState.CANCELLED }; assertEquals(AttachmentState.CANCELLED, f.repo.doc.attachment(fresh.id).state) }
    @Test fun backgroundCancelsCallerAndDiscardsNoncooperativeLateImportWithoutAutoResume() = runBlocking<Unit> { f.attachmentView(); f.holdOpen = true; val p = f.picker(); f.attachments.pickerResult(p.ticketId, "content://fixture.documents/document/source", 1); assertTrue(f.opened.await(5, TimeUnit.SECONDS)); f.connections.foregroundChanged(false); f.attachmentState { it.rows.isEmpty() }; withTimeout(5000) { while (f.repo.doc.attachment(p.id).state == AttachmentState.IMPORTING) delay(10) }; assertEquals(AttachmentState.PAUSED, f.repo.doc.attachment(p.id).state); assertTrue(f.providerIo.busy); f.releaseOpen.countDown(); withTimeout(5000) { while (f.providerIo.busy) delay(10) }; f.connections.foregroundChanged(true); withTimeout(5000) { f.connections.state.first { it.foreground } }; delay(60); assertTrue(f.repo.doc.chat!!.messages.isEmpty()); assertTrue(f.attachmentChunks.data.isEmpty()); assertEquals(1, f.imports.get()) }
    @Test fun providerCloseCannotEscapeDeadlineOrAllocateAnotherWorker() = runBlocking<Unit> { f.attachmentView(); f.holdClose = true; val p = f.picker(); f.attachments.pickerResult(p.ticketId, "content://fixture.documents/document/source", 1); assertTrue(f.closing.await(5, TimeUnit.SECONDS)); f.attachmentState { it.error == "PROVIDER_TIMEOUT" && !it.busy }; assertTrue(f.providerIo.busy); f.attachments.prepareImport("another", true); f.attachmentState { it.error == "ATTACHMENT_BUSY" }; assertEquals(1, f.imports.get()); assertEquals(1, f.probes.get()); f.releaseClose.countDown(); f.attachmentState { !it.providerBusy }; assertEquals(AttachmentState.VERIFIED, f.repo.doc.attachment(p.id).state) }
    @Test fun explicitExportUsesVerifiedBytesAndIndependentReadbackWithoutReplacingImport() = runBlocking<Unit> { val r = f.saved(); f.attachments.prepareExport(r.id, "copy.bin", true); val p = f.attachmentState { it.picker != null }.picker!!; assertTrue(f.attachments.claimPicker(p.ticketId)); f.attachments.pickerResult(p.ticketId, "content://fixture.documents/tree/root", 3); f.attachmentState { it.rows.single().exports.singleOrNull()?.state == ExportState.VERIFIED && !it.busy }; assertArrayEquals(f.plain, f.exported.toByteArray()); assertEquals(1, f.creates.get()); assertEquals(1, f.writes.get()); assertEquals(r.secret, f.repo.doc.attachment(r.id).secret) }
    @Test fun protectedStateWriteFailureLatchesNetworkingBeforePickerOrProvider() = runBlocking<Unit> { f.attachmentView(); f.repo.failWrite = true; f.attachments.prepareImport("private", true); withTimeout(5000) { f.connections.state.first { it.error == "STORAGE_UNAVAILABLE" } }; assertFalse(f.connections.state.value.transportAllowed); assertTrue(f.attachments.state.value.rows.isEmpty()); assertNull(f.attachments.state.value.picker); assertEquals(0, f.probes.get()); assertEquals(0, f.imports.get()) }
}
